package api

import (
	"embed"
	"io/fs"
	"net/http"

	"github.com/go-chi/chi/v5"
)

//go:embed all:webdist
var webDist embed.FS

// mountGUI serves the embedded single-page app at / and /static/*.
// The webdist directory is generated by `make sync-web` from web/dist
// (single source of truth) and is git-ignored.
func mountGUI(r *chi.Mux) {
	sub, err := fs.Sub(webDist, "webdist")
	if err != nil {
		return
	}
	r.Get("/", func(w http.ResponseWriter, req *http.Request) {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		data, err := fs.ReadFile(sub, "index.html")
		if err != nil {
			http.Error(w, "gui not embedded", 500)
			return
		}
		w.WriteHeader(200)
		_, _ = w.Write(data)
	})
	r.Handle("/static/*", http.StripPrefix("/static/", http.FileServer(http.FS(sub))))
}
